#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trisolv.h"

/* -------------------------------------------------------------------------
 * Tunable kernel parameters.
 *
 * TRISOLV_J_UNROLL_FACTOR:
 *   Hint for the compiler about how aggressively to unroll the inner
 *   j-loop in kernel_trisolv.  The pragma only affects code generation
 *   and does not change the numerical result or loop bounds.
 * ------------------------------------------------------------------------- */
#ifndef TRISOLV_J_UNROLL_FACTOR
#define TRISOLV_J_UNROLL_FACTOR 8
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      x[i] = - 999;
      b[i] =  i ;

      /* Use a row pointer to slightly improve locality and let the
         compiler keep the base address in a register.  The arithmetic
         expression is kept identical to the original version to
         preserve floating-point evaluation order. */
      DATA_TYPE* Li = L[i];

      for (j = 0; j <= i; j++)
        Li[j] = (DATA_TYPE) (i+n-j+1)*2/n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Create local restrict-qualified aliases for x and b.  Within this
     function we only use those aliases, which is valid because the
     PolyBench driver always passes distinct arrays for L, x, and b.
     This gives the compiler more freedom to keep values in registers.
   - Access each row of L through a local pointer (Li) to avoid
     recomputing the row base address inside the inner loop.
   - Accumulate the value of x[i] in a scalar register (xi) instead of
     updating x[i] in memory on every inner-loop iteration.  This keeps
     the original evaluation order and thus preserves the numerical
     result, while reducing memory traffic.
   - Use a GCC unroll pragma on the inner loop, controlled by the
     TRISOLV_J_UNROLL_FACTOR tuning macro, to increase instruction-level
     parallelism on wide-issue cores.
*/
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases improve the compiler's ability
     to optimize memory accesses, while we still obey their contract by
     never using the original parameter names inside the kernel. */
  DATA_TYPE *restrict x_ptr = x;
  DATA_TYPE *restrict b_ptr = b;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Pointer to the current row of L.  Using a row pointer helps
         with data locality and keeps the base address in a register. */
      const DATA_TYPE *restrict Li = L[i];

      /* Start from b[i] and perform the forward substitution in a
         scalar variable.  This avoids repeated loads/stores of x[i]
         inside the inner loop.  The sequence of arithmetic operations
         is identical to the original loop nest. */
      DATA_TYPE xi = b_ptr[i];

      /* Subtract the contribution of previously computed x[j] values
         (0 <= j < i).  The loop bounds and order are unchanged; we
         only provide an unrolling hint to the compiler. */
#pragma GCC unroll TRISOLV_J_UNROLL_FACTOR
      for (j = 0; j < i; j++)
        xi -= Li[j] * x_ptr[j];

      /* Divide by the diagonal element to finalize x[i]. */
      xi /= Li[i];
      x_ptr[i] = xi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
