/*
 * Main computational kernel. The whole function will be timed,
 * including the call and return.
 *
 * Optimizations applied (semantics-preserving):
 *  - Scalar replacement of x[i] by a local accumulator (xi) to keep
 *    the current row's result in a register instead of memory.
 *  - Use of local restrict-qualified pointers (Lr, xr, br) to give
 *    the compiler stronger aliasing guarantees.
 *  - Row pointer hoisting: rowLi points directly to the i-th row,
 *    reducing address arithmetic inside the inner loop.
 *  - Manual unrolling of the inner loop by a factor of 4 to expose
 *    more instruction-level parallelism and help vectorization.
 *
 * The mathematical computation is unchanged:
 *   for each i,
 *      x[i] = ( b[i] - sum_{j=0}^{i-1} L[i][j] * x[j] ) / L[i][i]
 */
static
void kernel_trisolv [[gnu::flatten, gnu::noinline]] (int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
