   * These are the only pointers used to access the underlying arrays
   * in the hot loop, so the restrict contract is respected. */
  const int n_local = n;
  DATA_TYPE (*restrict Lr)[n_local] = L;
  DATA_TYPE *restrict xr = x;
  DATA_TYPE *restrict br = b;

