  for (int i = 0; i < _PB_N; i++)
    {
      /* Hoist row pointer: contiguous access along j dimension. */
      DATA_TYPE *restrict rowLi = Lr[i];

      /* Keep the running value for x[i] in a register.
       * This is equivalent to:
       *   x[i] = b[i];
       *   for (j = 0; j < i; ++j)
       *     x[i] -= L[i][j] * x[j];
       * but avoids repeated memory traffic on x[i]. */
      DATA_TYPE xi = br[i];

      int j = 0;

      /* Unroll the inner loop by 4.
       * This keeps the iteration space exactly the same and only
       * restructures how iterations are grouped. */
      int limit = i & ~3; /* largest multiple of 4 less than or equal to i */

      for (; j < limit; j += 4)
      {
        xi -= rowLi[j]     * xr[j];
        xi -= rowLi[j + 1] * xr[j + 1];
        xi -= rowLi[j + 2] * xr[j + 2];
        xi -= rowLi[j + 3] * xr[j + 3];
      }

      /* Handle remaining iterations (0 to 3 of them). */
      for (; j < i; j++)
      {
        xi -= rowLi[j] * xr[j];
      }

      /* Final normalization by the diagonal element. */
      xr[i] = xi / rowLi[i];
    }
