   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use local restrict-qualified pointers for x and b to improve alias
     analysis and enable more aggressive optimization.
   - Accumulate the running value of x[i] in a local register variable
     (xi) instead of repeatedly reading and writing x[i] in memory.
   - Manually unroll the inner loop over j by a small, tunable factor
     (TRISOLV_J_UNROLL = 1, 2, or 4) to increase instruction-level
     parallelism while preserving the exact operation order.
   - Use a row pointer Li = L[i] to avoid recomputing the row address.
*/
static
void kernel_trisolv[[gnu::flatten, gnu::noinline]](int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  /* Local restrict-qualified aliases:
     PolyBench allocates L, x and b as distinct arrays, so they do not
     alias each other.  Telling the compiler this enables better
     scheduling and vectorization opportunities for the hot loop. */
  DATA_TYPE *restrict x_ = (DATA_TYPE *restrict) x;
  DATA_TYPE *restrict b_ = (DATA_TYPE *restrict) b;

  const int n_inner = _PB_N;

  int i;

#pragma scop
  for (i = 0; i < n_inner; i++)
    {
      /* Pointer to the current row of L; using a row pointer improves
         data locality and avoids repeated address calculations.  The
         restrict qualifier expresses that this row does not overlap
         with x_ or b_. */
      DATA_TYPE *restrict Li = L[i];

      /* Accumulator kept in a register: this replaces repeated
         loads/stores of x[i] inside the inner loop. */
      DATA_TYPE xi = b_[i];

      int j = 0;

      /* Inner triangular loop: xi = b[i] - sum_{j < i} L[i][j] * x[j].
         The order of floating-point operations is preserved in all
         cases below; only the number of operations scheduled per loop
         iteration changes. */
#if TRISOLV_J_UNROLL == 1

      for (; j < i; ++j)
        {
          xi -= Li[j] * x_[j];
        }

#elif TRISOLV_J_UNROLL == 2

      for (; j + 1 < i; j += 2)
        {
          xi -= Li[j]     * x_[j];
          xi -= Li[j + 1] * x_[j + 1];
        }
      /* Handle the remaining 0 or 1 iteration. */
      for (; j < i; ++j)
        {
          xi -= Li[j] * x_[j];
        }

#elif TRISOLV_J_UNROLL == 4

      for (; j + 3 < i; j += 4)
        {
          xi -= Li[j]     * x_[j];
          xi -= Li[j + 1] * x_[j + 1];
          xi -= Li[j + 2] * x_[j + 2];
          xi -= Li[j + 3] * x_[j + 3];
        }
      /* Handle the remaining 0–3 iterations. */
      for (; j < i; ++j)
        {
          xi -= Li[j] * x_[j];
        }

#else
# error "Unsupported TRISOLV_J_UNROLL value (only 1, 2, or 4 are allowed)."
#endif

      /* Final division for this row (forward substitution step). */
      xi /= Li[i];
      x_[i] = xi;
    }
#pragma endscop

