 * Must be >= 1. Values like 1, 2, 4, or 8 are reasonable choices.
 * This is a compile-time constant that can be overridden at
 * compilation time, e.g.:
 *    -DTRISOLV_INNER_UNROLL=8
 */
#ifndef TRISOLV_INNER_UNROLL
# define TRISOLV_INNER_UNROLL 4
#endif

#if TRISOLV_INNER_UNROLL < 1
# error "TRISOLV_INNER_UNROLL must be at least 1"
#endif


/* Array initialization. */
static
void init_array(int n,
		DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		DATA_TYPE POLYBENCH_1D(x,N,n),
		DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Use local restrict-qualified pointers to help the compiler
     optimize accesses (PolyBench guarantees non-aliasing here). */
  DATA_TYPE (* __restrict__ L_)[n] = L;
  DATA_TYPE * __restrict__ x_      = x;
  DATA_TYPE * __restrict__ b_      = b;

  for (i = 0; i < n; i++)
    {
      x_[i] = (DATA_TYPE)-999;
      b_[i] = (DATA_TYPE)i;

      DATA_TYPE * __restrict__ Lrow = L_[i];

      for (j = 0; j <= i; j++)
        /* Keep the same arithmetic structure as the original:
           (DATA_TYPE)(i+n-j+1)*2/n
           == ((DATA_TYPE)(i+n-j+1) * 2) / n
        */
	Lrow[j] = (DATA_TYPE)(i + n - j + 1) * 2 / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static __attribute__((noinline))
void kernel_trisolv(int n,
		    DATA_TYPE POLYBENCH_2D(L,N,N,n,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(b,N,n))
{
  int i, j;

  /* Local restrict-qualified aliases to enable better optimization.
     According to the PolyBench specification, these arrays do not alias. */
  DATA_TYPE (* __restrict__ L_)[n]   = L;
  DATA_TYPE * __restrict__ x_        = x;
  const DATA_TYPE * __restrict__ b_  = b;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    {
      /* Keep x[i] in a register (xi) for the whole inner loop.
         We replicate the original floating-point evaluation order:
           original:
             x[i] = b[i];
             for (j = 0; j < i; ++j)
               x[i] -= L[i][j] * x[j];
             x[i] = x[i] / L[i][i];
           optimized:
             xi = b[i];
             ... same sequence of "xi -= L[i][j] * x[j]" ...
             xi /= L[i][i];
             x[i] = xi;
         The sequence of operations and their order is unchanged. */
      DATA_TYPE xi = b_[i];

      const DATA_TYPE * __restrict__ Lrow = L_[i];

      /* Unrolled inner loop over j, controlled by TRISOLV_INNER_UNROLL.
         We compute a multiple of TRISOLV_INNER_UNROLL elements per
         outer j-iteration, but still in strictly increasing j order. */
      int j_limit = (i / TRISOLV_INNER_UNROLL) * TRISOLV_INNER_UNROLL;

      j = 0;
      for (; j < j_limit; j += TRISOLV_INNER_UNROLL)
        {
          /* Very small inner loop; ask GCC to unroll it completely. */
#pragma GCC unroll  /* hint for the inner u-loop */
          for (int u = 0; u < TRISOLV_INNER_UNROLL; ++u)
            {
              xi -= Lrow[j + u] * x_[j + u];
            }
        }

      /* Handle any remaining elements (at most TRISOLV_INNER_UNROLL-1). */
      for (; j < i; ++j)
        {
          xi -= Lrow[j] * x_[j];
        }

      /* Divide by the diagonal element to complete x[i]. */
      xi /= Lrow[i];
      x_[i] = xi;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(L, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trisolv (n, POLYBENCH_ARRAY(L), POLYBENCH_ARRAY(x), POLYBENCH_ARRAY(b));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(L);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(b);

  return 0;
}
